#include <QCoreApplication>
#include <QFile>
#include <QDebug>
#include <kzip.h>
#include <karchive.h>

int main(int argc, char **argv)
{
    QCoreApplication app(argc, argv);

    if (argc < 2) {
        qWarning() << "Usage: test_poc <zipfile>";
        return 1;
    }

    KZip zip(argv[1]);
    if (!zip.open(QIODevice::ReadOnly)) {
        qWarning() << "Cannot open ZIP";
        return 1;
    }

    const KArchiveDirectory *root = zip.directory();
    if (root) {
        qDebug() << "Root entries:" << root->entries();
        const KArchiveEntry *e = root->entry("a");
        if (e && e->isDirectory()) {
            const KArchiveDirectory *dir = static_cast<const KArchiveDirectory*>(e);
            qDebug() << "Dir a entries:" << dir->entries();
        }
    }

    zip.close();
    qDebug() << "Success - no crash!";
    return 0;
}
EOF
